def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    elements = [t.get('element') for t in sites]
    counts = {}
    for i in range(n):
        element = elements[i]
        counts[element] = counts.get(element, 0.0) + occ[i]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    expected = 1.0 - sum((x / atoms) ** 2 for x in counts.values())
    nearest = [0.0 for t in sites]
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            if occ[i] > 0 and occ[j] > 0 and (nearest[i] == 0 or d < nearest[i]):
                nearest[i] = d
    unlike = 0.0
    weight = 0.0
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            if occ[i] > 0 and occ[j] > 0 and nearest[i] > 0:
                w = occ[i] * occ[j] * (nearest[i] / d) ** 6
                weight += w
                if elements[i] != elements[j]:
                    unlike += w
    if weight <= 0:
        return 0.0
    return unlike / weight - expected

